const {contextBridge,ipcRenderer,webUtils}=require('electron');
contextBridge.exposeInMainWorld('mainsAgentsDesktop',{files:{pathForFile:file=>webUtils.getPathForFile(file),selectVideos:()=>ipcRenderer.invoke('files:select-videos'),selectAttachments:kind=>ipcRenderer.invoke('files:select-attachments',kind),attachmentInfo:paths=>ipcRenderer.invoke('files:attachment-info',paths),savePasted:(bytes,type)=>ipcRenderer.invoke('files:save-pasted',bytes,type),select:()=>Promise.resolve([]),inspect:()=>Promise.resolve([]),verify:()=>Promise.resolve([]),open:()=>Promise.resolve(false),reveal:()=>Promise.resolve(false)},state:{profile:'handoff-test',hasProfile:()=>Promise.resolve(true),read:(_profile,key)=>ipcRenderer.invoke('test:read',key),write:(_profile,key,value)=>ipcRenderer.invoke('test:write',key,value),readAll:()=>ipcRenderer.invoke('test:all')}});
